package com.finflow.fraud; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.concurrent.*; @RestController @RequestMapping("/api/v1/fraud") class FraudController{record Req(BigDecimal amount,String customerId){} record Decision(String decision,String reason,String ruleVersion){} @PostMapping("/evaluate") Decision eval(@RequestBody Req r,@RequestHeader(value="X-Failure-Mode",required=false)String mode)throws Exception{if("slow".equals(mode))Thread.sleep(5000);if("error".equals(mode))throw new RuntimeException("Injected fraud outage");return r.amount().compareTo(new BigDecimal("2500"))>0?new Decision("REVIEW","AMOUNT_THRESHOLD","rules-2026.08"):new Decision("APPROVE","LOW_RISK","rules-2026.08");}}